# Codex SessionStart hook: stdout becomes extra developer context.
# Docs: https://developers.openai.com/codex/hooks

$ErrorActionPreference = 'Stop'

try {
    if ([Console]::IsInputRedirected) {
        [void][Console]::In.ReadToEnd()
    }
} catch {
}

$userHome = $env:USERPROFILE
if (-not $userHome) { exit 0 }

$agentsPath = Join-Path $userHome '.codex\AGENTS.md'
$cursorSkills = Join-Path $userHome '.cursor\skills'

$lines = @(
    '[Codex SessionStart hook]',
    "- Primary rules: read ``$agentsPath`` (Codex global AGENTS). Hooks only reinforce routing.",
    "- Skills: honor slash triggers in AGENTS.md (e.g. /codex, /MyStartupProject1); load disk SKILL.md first. Fallback: ``@`` attach SKILL paths.",
    "- BMAD: before executing bmad-* workflow steps, ReadFile ``${cursorSkills}\<bmad-id>\SKILL.md`` and linked workflow/checklist.",
    "- MCP lives in ``$(Join-Path $userHome '.codex\config.toml')``. Prefer Context7 for upstream docs; GitHub MCP needs env ``GITHUB_PERSONAL_ACCESS_TOKEN``.",
    ''
)

Write-Output ($lines -join [Environment]::NewLine)
exit 0
